// ============================================================
// EMPRESAS CONFIGURADAS
// Para agregar una empresa nueva: copiá una línea y completá
//   company_id → ID de la empresa en el sistema ChatBot
//   folder_id  → ID de la carpeta en Google Drive
//                (copialo desde la URL de Drive: /folders/ESTE_ID)
// ============================================================
const empresas = [
  {
    company_id: 'test2',
    folder_id:  '181SrJKfO0gBhhSQ8ZpyVPMwXffB2AfaR',
    nombre:     'Test 2'
  },
  {
    company_id: 'test3',
    folder_id:  '16PNA3gAgvtoamLgdhkLn3BQ8i_erJFmy',
    nombre:     'Test 3'
  },
  // { company_id: 'nueva-empresa', folder_id: 'ID_CARPETA_DRIVE', nombre: 'Nombre visible' },
];

return empresas.map(e => ({ json: e }));

// Registrar resultado de cada empresa
const resultados = $input.all().map(item => {
  const r = item.json;
  const estado = r.ok ? '✅ OK' : '❌ ERROR';
  const detalle = r.ok
    ? `${r.entries_count || 0} entradas actualizadas`
    : (r.error || 'sin detalle');
  return {
    json: {
      estado,
      empresa: r.company_id || '',
      detalle,
      mensaje: r.message || r.error || '',
      timestamp: new Date().toLocaleString('es-AR', { timeZone: 'America/Argentina/Buenos_Aires' }),
    }
  };
});

return resultados;
